mapper.select:
SELECT 
FROM notices n
LEFT JOIN users u ON u.user_id = n.user_id


        AND (
            n.title LIKE CONCAT('%', #{keyword}, '%')
            OR n.content LIKE CONCAT('%', #{keyword}, '%')
        )


        AND n.is_pinned = #{pinned}


ORDER BY n.is_pinned DESC, n.notice_id DESC
LIMIT #{limit} OFFSET #{offset}
